#include <unistd.h>
#include <sys/wait.h>

int sum_in_child(const int *values, int n, long *result) {
    int fd[2];
    if (pipe(fd) != 0) {
        return -1;
    }

    pid_t pid = fork();
    if (pid < 0) {
        close(fd[0]);
        close(fd[1]);
        return -1;
    }

    if (pid == 0) {
        /* Child: close read end, compute sum, write, exit */
        close(fd[0]);
        long sum = 0;
        for (int i = 0; i < n; i++) {
            sum += values[i];
        }
        ssize_t written = write(fd[1], &sum, sizeof(long));
        close(fd[1]);
        if (written != sizeof(long)) {
            _exit(1);
        }
        _exit(0);
    }

    /* Parent: close write end, read sum */
    close(fd[1]);
    ssize_t read_bytes = read(fd[0], result, sizeof(long));
    close(fd[0]);

    if (read_bytes != sizeof(long)) {
        /* Wait to avoid zombie even on read failure */
        int status;
        waitpid(pid, &status, 0);
        return -1;
    }

    /* Wait for child and verify it exited with status 0 */
    int status;
    if (waitpid(pid, &status, 0) != pid) {
        return -1;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        return -1;
    }

    return 0;
}
