import java.util.*;
import java.util.stream.Collectors;
import java.util.stream.Stream;

public class Report {

    public record Student(String name, String group, List<Integer> grades) {
        Optional<Double> mean() {
            if (grades == null || grades.isEmpty()) {
                return Optional.empty();
            }
            return Optional.of(grades.stream().mapToDouble(Integer::doubleValue).average().orElseThrow());
        }
    }

    static Map<String, Double> averageByGroup(List<Student> students) {
        return students.stream()
                .filter(s -> s.mean().isPresent())
                .collect(Collectors.groupingBy(
                        Student::group,
                        Collectors.mapping(
                                s -> s.mean().orElseThrow(),
                                Collectors.collectingAndThen(
                                        Collectors.toList(),
                                        list -> list.stream().mapToDouble(Double::doubleValue).average().orElse(0.0)))));
    }

    static List<String> topStudents(List<Student> students, int n) {
        return students.stream()
                .filter(s -> s.mean().isPresent())
                .sorted(Comparator.comparingDouble((Student s) -> s.mean().orElseThrow()).reversed()
                        .thenComparing(Student::name))
                .limit(n)
                .map(Student::name)
                .collect(Collectors.toList());
    }

    static Optional<Student> best(List<Student> students, String group) {
        return students.stream()
                .filter(s -> group.equals(s.group()))
                .filter(s -> s.mean().isPresent())
                .max(Comparator.comparingDouble((Student s) -> s.mean().orElseThrow()));
    }
}
